SELECT COUNT(*)
FROM download_logs
WHERE user_id = #{userId}
AND resource_id = #{resourceId}
AND deleted_at IS NULL

SELECT dl.id, dl.user_id, dl.resource_id, dl.points_used, dl.downloaded_at, dl.created_at, dl.updated_at, dl.deleted_at, u.username, r.name as resource_name FROM download_logs dl LEFT JOIN users u ON dl.user_id = u.id LEFT JOIN resources r ON dl.resource_id = r.id
dl.deleted_at IS NULL
AND dl.user_id = #{userId}
AND dl.resource_id = #{resourceId}
ORDER BY dl.downloaded_at DESC, dl.id DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*)
FROM download_logs dl

    dl.deleted_at IS NULL

        AND dl.user_id = #{userId}


        AND dl.resource_id = #{resourceId}
